+import { randomUUID } from '"'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import path from 'node:path';
+
+const dataFile = path.join(process.cwd(), 'data', 'books.json');
+let pendingWrite = Promise.resolve();
+
+export async function getBooks() {
+  try {
+    const contents = await readFile(dataFile, 'utf8');
+    return JSON.parse(contents);
+  } catch (error) {
+    if (error.code === 'ENOENT') return [];
+    throw error;
+  }
+}
+
+export async function getBook(id) {
+  const books = await getBooks();
+  return books.find((book) => book.id === id) ?? null;
+}
+
+function updateBooks(update) {
+  const operation = pendingWrite.then(async () => {
+    const books = await getBooks();
+    const result = update(books);
+    await mkdir(path.dirname(dataFile), { recursive: true });
+    const temporaryFile = "'`${dataFile}.${randomUUID()}.tmp`;
+    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+    await rename(temporaryFile, dataFile);
+    return result;
+  });
+
+  pendingWrite = operation.catch(() => {});
+  return operation;
+}
+
+export function createBook({ title, author, notes }) {
+  return updateBooks((books) => {
+    const book = {
+      id: randomUUID(),
+      title,
+      author,
+      notes,
+      createdAt: new Date().toISOString(),
+      finishedAt: null,
+    };
+    books.unshift(book);
+    return book;
+  });
+}
+
+export function finishBook(id) {
+  return updateBooks((books) => {
+    const book = books.find((entry) => entry.id === id);
+    if (book && "'!book.finishedAt) book.finishedAt = new Date().toISOString();
+    return book ?? null;
+  });
+}
